/* Physical TI-84 guidance. The embedded study calculator is a separate subset. */
(function(root){
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),display=s=>s.replace(/acos\(/g,'cos⁻¹(').replace(/asin\(/g,'sin⁻¹(').replace(/atan\(/g,'tan⁻¹(').replace(/sqrt\(/g,'√(').replace(/\bpi\b/g,'π');
 const common='Use [MODE] to select the stated angle mode and FLOAT. Use [2nd][x²] for √ and [2nd][SIN/COS/TAN] for an inverse trig function. Enter a leading negative with [(-)], not the subtraction key. Use explicit × and parentheses around negative numbers. After each expression press [STO→], [ALPHA], the indicated letter, then [ENTER]. Stored variables retain more precision than a rounded display; use those letters in later steps. These A–Z letters are calculator memory locations, not the physical force names.';
 function renderStep(step,digits=6){if(!step.ti84)return '';const math=root.StudyMath||(typeof require!=='undefined'?require('./math.js'):null),memory=step.ti84.memory||[],formula=row=>math?'<div class="math"><math><mrow><mtext>'+esc(row.label)+'</mtext><mo>=</mo>'+math.markup(math.parse(row.expression)).replace(/<mi>([a-z])<\/mi>/g,(_,letter)=>'<mi>'+letter.toUpperCase()+'</mi>')+'<mo>≈</mo>'+math.markup(math.parse(String(Number(row.value.toPrecision(digits)))))+'</mrow></math></div>':'';return `<div class="ti84-recipe"><h3>TI-84 Plus · ${step.ti84.mode==='RAD'?'RADIAN':'DEGREE'}</h3><p>${common}</p>${memory.length?'<details><summary>Calculator memory from previous steps</summary><ul>'+memory.map(row=>'<li><strong>'+row.store+'</strong>: '+esc(row.label)+'</li>').join('')+'</ul></details>':''}<ol>${step.ti84.rows.map(row=>`<li><strong>${esc(row.label)}</strong>${formula(row)}<code>${esc(display(row.expression))} → ${row.store}</code><span>Expected display ≈ ${Number(row.value.toPrecision(digits))}</span></li>`).join('')}</ol><p><strong>Keep stored values for intermediate steps.</strong> Round the reported answer to your selected significant figures. The displayed approximation is not an instruction to retype a rounded value.</p></div>`;}
 const calculus=()=>`<div class="ti84-recipe"><h3>TI-84 Plus · calculus workflow</h3><p><strong>Set RADIAN for standard calculus trig rules.</strong> Use [MATH] → 9:fnInt( for a numerical definite integral. In Classic mode enter <code>fnInt(expression,X,lower,upper)</code>. In MathPrint fill the expression, variable and bound fields.</p><p>For example, enter <code>fnInt(12*X^2,X,0,3)</code> for force and <code>fnInt(X*(12*X^2),X,0,3)</code> for first moment. Store the first result in A and the second in B; enter <code>B/A</code> for the location.</p><p><strong>The standard TI-84 Plus does not produce a symbolic antiderivative.</strong> Work out the integration rule on paper, then evaluate its bounds on the calculator. nDeriv(expression,X,value) gives an approximate derivative at one point; it is a numerical check, not a proof for all X. Choose regular points inside the domain.</p><p><strong>Model distinction:</strong> these entries are for your physical TI-84 Plus. The app’s TI-style calculator supports a smaller set of commands and does not run fnInt, nDeriv, or STO programs.</p><p><a href="https://education.ti.com/en/customer-support/knowledge-base/ti-83-84-plus-family/product-usage/34694" target="_blank" rel="noopener">TI’s fnInt instructions</a></p></div>`;
 const direction=()=>'<p><strong>TI-84 direction:</strong> use [2nd][TAN] for tan⁻¹(Ry/Rx). When Rx &lt; 0, add 180°. When Rx &gt; 0 and Ry &lt; 0, add 360° for a 0–360° answer. If Rx = 0, use 90° for Ry &gt; 0 or 270° for Ry &lt; 0. If both vanish, direction is undefined. The app’s atan2 notation is mathematical shorthand; it is not a standard TI-84 command.</p>';
 const api={renderStep,calculus,common,display,direction};root.TI84=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
